package com.xianshuyuan.scm.customer.controller;
import com.xianshuyuan.scm.common.api.*;import com.xianshuyuan.scm.customer.dto.*;import com.xianshuyuan.scm.customer.service.*;import com.xianshuyuan.scm.customer.vo.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @Validated @RequestMapping("/api/customers") public class CustomerController {private final CustomerService service;private final CustomerQueryService query;public CustomerController(CustomerService s,CustomerQueryService q){service=s;query=q;}@GetMapping public ApiResponse<PageData<CustomerResponse>> page(@RequestParam(defaultValue="1") @Min(1) long page,@RequestParam(defaultValue="20") @Min(1) @Max(100) long pageSize,@RequestParam(required=false) String keyword,@RequestParam(required=false) Long customerTypeId){return ApiResponse.success(query.page(new CustomerPageQuery(page,pageSize,keyword,customerTypeId)));}@GetMapping("/{id}") public ApiResponse<CustomerResponse> get(@PathVariable long id){return ApiResponse.success(query.get(id));}@PostMapping public ApiResponse<Long> create(@Valid @RequestBody CustomerSaveRequest r){return ApiResponse.success(service.create(r));}@PutMapping("/{id}") public ApiResponse<Void> update(@PathVariable long id,@Valid @RequestBody CustomerSaveRequest r){service.update(id,r);return ApiResponse.success(null);}@PutMapping("/{id}/status") public ApiResponse<Void> status(@PathVariable long id,@Valid @RequestBody CustomerStatusRequest r){service.updateStatus(id,r.version(),r.status());return ApiResponse.success(null);}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable long id,@RequestParam @Min(0) int version){service.delete(id,version);return ApiResponse.success(null);}}
